import (
	"fmt"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// NewSprintf creates a formatted string binding that combines multiple data bindings.
// When any source binding changes, the formatted string is automatically updated.
// Set() parses the string back using fmt.Sscanf and updates each source binding.
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBinding{
		format:   format,
		bindings: bindings,
	}

	// Listen to all source bindings
	for _, b := range bindings {
		b.AddListener(s)
	}

	return s
}

// StringToStringWithFormat wraps a String binding with a format string.
// If format is "%s", returns the original binding directly.
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

type sprintfBinding struct {
	base
	format   string
	bindings []DataItem
	lastErr  error
}

func (s *sprintfBinding) Get() (string, error) {
	if s.lastErr != nil {
		return "", s.lastErr
	}

	values := make([]interface{}, len(s.bindings))
	for i, b := range s.bindings {
		val, err := s.getValue(b)
		if err != nil {
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *sprintfBinding) Set(str string) error {
	// Prepare pointers for Sscanf
	values := make([]interface{}, len(s.bindings))
	for i, b := range s.bindings {
		values[i] = s.getPointerForType(b)
	}

	// Parse the string
	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}
	if n != len(s.bindings) {
		return fmt.Errorf("expected %d values, got %d", len(s.bindings), n)
	}

	// Set each binding with the parsed value
	for i, b := range s.bindings {
		if err := s.setValue(b, values[i]); err != nil {
			return err
		}
	}

	return nil
}

func (s *sprintfBinding) DataChanged() {
